beispiel_code:
def ist_gerade(zahl):
    return zahl % 2 == 0

for i in range(1, 6):
    print(i, "gerade" if ist_gerade(i) else "ungerade")

beispiel_plus:
def flaeche(b, h):
    return b * h
print("flaeche:", flaeche(5, 3))

beispiel_profi:
def fakultaet(n):
    ergebnis = 1
    for i in range(1, n + 1):
        ergebnis = ergebnis * i
    return ergebnis
